        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}$this->output->set_header('Cache-Control: no-store');require_once APPPATH.'services/CompanyPostRefundCancellation.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$csrf=$this->session->userdata('company_post_refund_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_post_refund_csrf',$csrf);}$service=new CompanyPostRefundCancellation($this->db,db_prefix());$detail=null;$error=null;
